structure(expression(library(digest), library(dplyr), library(ggplot2), library(gt), library(readr), library(scales), library(tibble), library(tidyr), root <- normalizePath(Sys.getenv("QUARTO_PROJECT_DIR"), winslash = "/", mustWork = TRUE), stopifnot(getRversion() >= numeric_version("4.6.1"), getRversion() < numeric_version("4.7.0")), absolute_path <- function(path) {
