code:
#| label: setup-h06-daily-preparation
#| include: false

suppressPackageStartupMessages({
  library(dplyr)
  library(gt)
  library(knitr)
  library(readr)
  library(tibble)
  library(tidyr)
})

locate_project_root <- function(start = getwd()) {
  candidate <- normalizePath(start, winslash = "/", mustWork = TRUE)
  repeat {
    if (
      file.exists(file.path(candidate, "renv.lock")) &&
        file.exists(file.path(candidate, "_quarto.yml"))
    ) {
      return(candidate)
    }
    parent <- dirname(candidate)
    if (identical(parent, candidate)) {
      stop("Could not locate the project root", call. = FALSE)
    }
    candidate <- parent
  }
}

project_root <- locate_project_root()

if (!identical(as.character(getRversion()), "4.6.1")) {
  stop("H06_daily preparation requires R 4.6.1", call. = FALSE)
}

read_h06d <- function(filename) {
  readr::read_csv(
    file.path(
      project_root,
      "artifacts/11_source_data/H06_daily",
      filename
    ),
    show_col_types = FALSE,
    na = c("", "NA")
  )
}

compact_gt <- function(
  data,
  groupname_col = NULL,
  source_note = NULL,
  font_size = 11.5
) {
  output <- if (inherits(data, "gt_tbl")) {
    data
  } else {
    gt::gt(data, groupname_col = groupname_col)
  }
  output <- output |>
    gt::opt_row_striping() |>
    gt::sub_missing(missing_text = "—") |>
    gt::tab_options(
      table.width = gt::pct(100),
      table.font.size = gt::px(font_size),
      data_row.padding = gt::px(4),
      column_labels.font.weight = "600",
      source_notes.font.size = gt::px(10.5),
      row_group.padding = gt::px(4)
    )
  if (!is.null(source_note)) {
    output <- output |>
      gt::tab_source_note(gt::md(source_note))
  }
  output
}

format_range <- function(minimum, maximum) {
  ifelse(
    minimum == maximum,
    format(minimum, big.mark = ",", scientific = FALSE, trim = TRUE),
    paste0(
      format(minimum, big.mark = ",", scientific = FALSE, trim = TRUE),
      "–",
      format(maximum, big.mark = ",", scientific = FALSE, trim = TRUE)
    )
  )
}

input_provenance <- read_h06d(
  "H06_daily_preparation_input_provenance.csv"
)
metric_registry <- read_h06d(
  "H06_daily_preparation_metric_registry.csv"
)
predictor_registry <- read_h06d(
  "H06_daily_preparation_predictor_registry.csv"
)
model_routes <- read_h06d(
  "H06_daily_preparation_model_routes.csv"
)
exact_samples <- read_h06d(
  "H06_daily_preparation_exact_samples.csv"
)
sample_roles <- read_h06d(
  "H06_daily_preparation_sample_role_summary.csv"
)
primary_samples <- read_h06d(
  "H06_daily_preparation_primary_sample_by_metric.csv"
)
predictor_support <- read_h06d(
  "H06_daily_preparation_primary_predictor_support.csv"
)
site_support <- read_h06d(
  "H06_daily_preparation_primary_site_support.csv"
)
multiplicity <- read_h06d(
  "H06_daily_preparation_multiplicity_families.csv"
)
diagnostics <- read_h06d(
  "H06_daily_preparation_diagnostic_summary.csv"
)
sensitivity_registry <- read_h06d(
  "H06_daily_preparation_sensitivity_registry.csv"
)
temporal_support <- read_h06d(
  "H06_daily_preparation_temporal_support.csv"
)
code_map <- read_h06d("H06_daily_preparation_code_map.csv")
output_trace <- read_h06d("H06_daily_preparation_output_trace.csv")
figure_alt <- read_h06d("H06_daily_preparation_figure_alt_text.csv")

joint_registry <- readr::read_csv(
  file.path(
    project_root,
    paste0(
      "artifacts/06_model_data/H06_daily/",
      "H06_daily_joint_context_exploratory_frame_registry.csv"
    )
  ),
  show_col_types = FALSE
)
temporal_formula <- readr::read_csv(
  file.path(
    project_root,
    paste0(
      "artifacts/06_model_data/H06_daily/",
      "H06_daily_temporal_h02_formula_registry.csv"
    )
  ),
  show_col_types = FALSE
)

stopifnot(
  all(input_provenance$verification_status == "PASS"),
  all(input_provenance$expected_sha256 == input_provenance$observed_sha256),
  nrow(metric_registry) == 15L,
  identical(as.integer(metric_registry$metric_slot), 1:15),
  nrow(predictor_registry) == 3L,
  nrow(model_routes) == 15L,
  nrow(exact_samples) == 522L,
  nrow(sample_roles) == 12L,
  nrow(primary_samples) == 15L,
  nrow(site_support) == 405L,
  nrow(multiplicity) == 12L,
  nrow(diagnostics) == 25L,
  nrow(temporal_support) == 6L,
  nrow(joint_registry) == 14L,
  nrow(temporal_formula) == 1L,
  nrow(figure_alt) == 1L,
  all(metric_registry$analysis_unit == "participant-day"),
  all(multiplicity$named_slots == 15L),
  all(multiplicity$named_na_slots == 1L)
)

