placement_label <- function(x) {
  ifelse(x == "glasses", "Near eye (primary)", "Chest (complementary)")
}

predictor_label <- function(x) {
  ifelse(
    x == "age",
    "Age, per 10 years",
    "Measured biological sex, Female minus Male"
  )
}

p_markdown <- function(display, significant = FALSE) {
  ifelse(significant, paste0("**", display, "**"), display)
}

sample_display <- function(data) {
  ifelse(
    data$analysis_unit == "participant",
    sprintf(
      "%d participants/observations; %d contributing participant-days",
      data$participants,
      round(data$contributing_participant_days)
    ),
    sprintf(
      "%d participants; %d participant-days/observations",
      data$participants,
      data$participant_days
    )
  )
}

support_display <- function(hours) {
  ifelse(
    is.finite(hours),
    format(round(hours, 1), big.mark = ",", trim = TRUE),
    "—"
  )
}

h10_gt <- function(data, title = NULL, note = NULL, size = 12) {
  output <- data |>
    gt() |>
    opt_align_table_header(align = "left") |>
    opt_row_striping() |>
    sub_missing(missing_text = "—") |>
    tab_options(
      table.width = pct(100),
      container.width = pct(100),
      container.overflow.x = TRUE,
      table.font.size = px(size),
      data_row.padding = px(3),
      heading.align = "left",
      source_notes.font.size = px(max(10, size - 2))
    )
  if (!is.null(title)) {
    output <- output |> tab_header(title = md(title))
  }
  if (!is.null(note)) {
    output <- output |> tab_source_note(md(note))
  }
  output
}

main_result_table <- function(data, placement, predictor) {
  data |>
    filter(
      .data$placement == .env$placement,
      .data$predictor == .env$predictor
    ) |>
    arrange(.data$metric_order) |>
    transmute(
      Metric = .data$manuscript_name,
      `Effect (95% CI)` = .data$effect_95_ci_display,
      `Raw p` = .data$p_raw_display,
      `FDR-adjusted p` = p_markdown(
        .data$p_adjusted_display,
        .data$adjusted_significant
      ),
      Sample = sample_display(dplyr::pick(dplyr::everything())),
      `Valid support (h)` = support_display(
        .data$metric_support_valid_hours
      ),
      Assessment = str_replace_all(.data$final_assessment, "_", " ")
    ) |>
    h10_gt(
      title = paste0(
        placement_label(placement), ": ", predictor_label(predictor)
      ),
      note = paste0(
        "Effects are model-based estimates with 95% confidence intervals. ",
        "Bold adjusted p-values satisfy the explicitly labelled FDR rule ",
        "within this 17-metric family. Valid support hours are shown where ",
        "the response has a metric-specific time window."
      ),
      size = 12
    ) |>
    fmt_markdown(columns = c(`Effect (95% CI)`, `FDR-adjusted p`))
}

retained_main_result_table <- function(data) {
  data |>
    filter(.data$adjusted_significant) |>
    mutate(
      placement_order = match(.data$placement, c("glasses", "chest")),
      predictor_order = match(
        .data$predictor,
        c("age", "biological_sex")
      )
    ) |>
    arrange(
      .data$placement_order,
      .data$predictor_order,
      .data$metric_order
    ) |>
    transmute(
      `Placement and role` = placement_label(.data$placement),
      Predictor = predictor_label(.data$predictor),
      Metric = .data$manuscript_name,
      `Practical association (95% CI)` = .data$effect_95_ci_display,
      `Raw p` = .data$p_raw_display,
      `FDR-adjusted p` = p_markdown(
        .data$p_adjusted_display,
        .data$adjusted_significant
      ),
      Sample = sample_display(dplyr::pick(dplyr::everything()))
    ) |>
    h10_gt(
      note = paste0(
        "Associations are site-adjusted estimates per 10-year age increase or ",
        "Female minus Male. Ratios are back-transformed to the practical ",
        "scale. Each FDR-adjusted p-value belongs to its sensor-position- and ",
        "predictor-specific complete 17-test family; bold values meet the ",
        "FDR-adjusted p < 0.050 rule. Samples give the exact fitted ",
        "participants and participant-day observations for these retained ",
        "daily-response results."
      ),
      size = 12
    ) |>
    fmt_markdown(
      columns = c(`Practical association (95% CI)`, `FDR-adjusted p`)
    ) |>
    cols_width(
      `Placement and role` ~ pct(14),
      Predictor ~ pct(15),
      Metric ~ pct(17),
      `Practical association (95% CI)` ~ pct(17),
      `Raw p` ~ pct(7),
      `FDR-adjusted p` ~ pct(9),
      Sample ~ pct(21)
    )
}

