code:
#| label: setup-h11-preparation
#| include: false

suppressPackageStartupMessages({
  library(dplyr)
  library(gt)
  library(knitr)
  library(readr)
  library(tibble)
  library(tidyr)
})

root_candidates <- unique(c(
  normalizePath(
    Sys.getenv("QUARTO_PROJECT_DIR", unset = getwd()),
    winslash = "/",
    mustWork = FALSE
  ),
  normalizePath(getwd(), winslash = "/", mustWork = TRUE),
  normalizePath(file.path(getwd(), "../../.."), winslash = "/", mustWork = FALSE)
))
is_project_root <- vapply(
  root_candidates,
  function(path) {
    file.exists(file.path(path, "renv.lock")) &&
      file.exists(file.path(
        path,
        "scripts/hypotheses/H11/build_h11_preparation_artifacts.R"
      ))
  },
  logical(1)
)
stopifnot(any(is_project_root))
root <- root_candidates[which(is_project_root)[1L]]
knitr::opts_knit$set(
  root.dir = file.path(root, "audit", "hypotheses", "H11")
)

source(file.path(root, "scripts/pipeline/paths_io.R"))
source(file.path(root, "scripts/pipeline/p_value_display.R"))

if (!identical(as.character(getRversion()), "4.6.1")) {
  stop("H11 preparation requires R 4.6.1", call. = FALSE)
}

read_h11_csv <- function(relative_path) {
  readr::read_csv(file.path(root, relative_path), show_col_types = FALSE)
}

prep_gt <- function(table, font_size = 12) {
  table |>
    gt::opt_row_striping() |>
    gt::sub_missing(missing_text = "Not available") |>
    gt::tab_options(
      table.width = gt::pct(100),
      table.font.size = gt::px(font_size),
      data_row.padding = gt::px(4),
      column_labels.font.weight = "600",
      source_notes.font.size = gt::px(11)
    )
}

format_count <- function(value) {
  format(value, big.mark = ",", scientific = FALSE, trim = TRUE)
}

format_p <- function(value) {
  nh_format_p_value(as.numeric(value))
}

frame_integrity <- read_h11_csv(
  paste0(
    "artifacts/11_source_data/H11/preparation/",
    "H11_preparation_frame_integrity.csv"
  )
)
sample_support <- read_h11_csv(
  paste0(
    "artifacts/11_source_data/H11/preparation/",
    "H11_preparation_sample_support.csv"
  )
)
input_identities <- read_h11_csv(
