    assert_condition(identical(current_dir, project_dir), "The post-render wrapper must run from the main Quarto project directory.")
    environment_project <- environment_value(environment, "QUARTO_PROJECT_DIR")
    if (nzchar(environment_project)) {
        assert_condition(identical(resolve_path(environment_project, project_dir, must_work = TRUE), project_dir), "QUARTO_PROJECT_DIR does not resolve to the current project directory.")
    }
    profile_path <- file.path(project_dir, "_quarto-nathealth.yml")
    assert_condition(file.exists(profile_path) && !dir.exists(profile_path), "The Nature Health profile is missing from the project directory.")
    output_value <- environment_value(environment, "QUARTO_PROJECT_OUTPUT_DIR")
    assert_condition(nzchar(output_value), "QUARTO_PROJECT_OUTPUT_DIR is missing.")
    expected_output_dir <- normalizePath(file.path(project_dir, "_build", "nathealth"), winslash = "/", mustWork = TRUE)
    declared_output_dir <- resolve_path(output_value, project_dir, must_work = TRUE)
    assert_condition(identical(declared_output_dir, expected_output_dir), paste0("QUARTO_PROJECT_OUTPUT_DIR must resolve exactly to ", "_build/nathealth for this profile."))
    list(project_dir = project_dir, output_dir = expected_output_dir, profile_path = normalizePath(profile_path, winslash = "/", mustWork = TRUE))
}, validate_audit_directory <- function(environment, project_dir) {
    audit_value <- environment_value(environment, "GT_HTML_SEMANTIC_AUDIT_DIR")
    if (!nzchar(audit_value)) {
