}, accepted_repair_engine_sha256 <- "7c949930fec862a4ce783c28d0256d36cb45de7c017bd9fcbb7cb910599463d1", load_repair_engine <- function(project_dir) {
    engine_path <- normalizePath(file.path(project_dir, "scripts", "report_harmonization", "repair_gt_html_semantics.R"), winslash = "/", mustWork = TRUE)
    assert_condition(path_is_within(engine_path, project_dir), "The accepted repair engine must resolve inside the project directory.")
    assert_condition(identical(digest(engine_path, file = TRUE, algo = "sha256", serialize = FALSE), accepted_repair_engine_sha256), "The gt HTML semantic repair engine does not match its accepted identity.")
    engine <- new.env(parent = globalenv())
