    values <- transform(data[[variable]])
    values <- values[is.finite(values)]
    denominator <- nrow(data)
    if (circular) {
        summary <- circular_descriptive_summary(values)
        display <- paste0(format_clock_minute(summary[["median"]]), " [", format_clock_minute(summary[["q1"]]), ", ", format_clock_minute(summary[["q3"]]), "]")
        minimum <- maximum <- NA_real_
    }
    else {
        summary <- c(mean = finite_mean(values), q1 = finite_quantile(values, 0.25), median = finite_median(values), q3 = finite_quantile(values, 0.75), resultant = NA_real_)
        minimum <- if (length(values)) 
            min(values)
        else NA_real_
        maximum <- if (length(values)) 
            max(values)
        else NA_real_
