structure(expression(replica_double_clock_scale <- function(compact = FALSE) {
    breaks <- if (compact) {
        c(0, 720, 1440, 2160, 2880)
    }
    else {
        c(0, 360, 720, 1080, 1440, 1800, 2160, 2520, 2880)
    }
    labels <- if (compact) {
        c("00", "12", "00", "12", "24")
    }
    else {
