}, make_site_map_replica_plot <- function(site_locations, world_map) {
    world_sf <- sf::st_sf(region = world_map$region, geometry = sf::st_as_sfc(world_map$wkt, crs = 4326))
    locations <- dplyr::mutate(site_locations, reader_site = replica_site_label(.data$site), label_text_colour = ifelse(.data$site == "IZTECH", "white", "black"), label = paste0(.data$reader_site, " — ", .data$country, ", ", format_coordinate_label(.data$latitude_deg, .data$longitude_deg)))
    label_layout <- data.frame(site = descriptive_site_order(), label_longitude = c(12.9, -127.2, 0, 20.6, 20.6, -127.2, 26.6, -84.1, -1.6), label_latitude = c(77, 52, 65, 60, 48, 40.4, 30, 19, -2), label_hjust = c(0.5, 0, 1, 0, 0, 0, 0.5, 0.5, 0.5), stringsAsFactors = FALSE)
    connection_layout <- data.frame(site = c("BAUA", "MPI", "TUM"), connection_longitude = c(0, 20.6, 20.6), connection_latitude = c(62, 60, 48), stringsAsFactors = FALSE)
    locations <- dplyr::left_join(dplyr::select(locations, -dplyr::any_of(c("label_longitude", "label_latitude", "label_hjust"))), label_layout, by = "site")
    country_colours <- dplyr::summarise(dplyr::group_by(locations, .data$country), colour = unname(descriptive_site_palette()[dplyr::first(.data$site)]), .groups = "drop")
    world_sf$fill_key <- ifelse(world_sf$region %in% country_colours$country, world_sf$region, NA_character_)
    locations_sf <- sf::st_as_sf(locations, coords = c("longitude_deg", "latitude_deg"), crs = 4326, remove = FALSE)
    projection <- "+proj=eqc"
    world_projected <- sf::st_transform(world_sf, crs = projection)
    locations_projected <- sf::st_transform(locations_sf, crs = projection)
    label_locations_sf <- sf::st_as_sf(locations, coords = c("label_longitude", "label_latitude"), crs = 4326, remove = FALSE)
    label_locations_projected <- sf::st_transform(label_locations_sf, crs = projection)
    point_coordinates <- sf::st_coordinates(locations_projected)
    label_coordinates <- sf::st_coordinates(label_locations_projected)
    label_data <- dplyr::mutate(locations, point_x = point_coordinates[, "X"], point_y = point_coordinates[, "Y"], label_x = label_coordinates[, "X"], label_y = label_coordinates[, "Y"])
