        show.legend = FALSE) + ggplot2::geom_label(data = label_data, ggplot2::aes(x = .data$label_x, y = .data$label_y, label = .data$label, fill = .data$site, colour = .data$label_text_colour, hjust = .data$label_hjust), linewidth = 0, size = 3.5, alpha = 0.84, label.padding = grid::unit(0.16, "lines"), inherit.aes = FALSE, show.legend = FALSE) + ggplot2::scale_fill_manual(values = fill_values, na.value = "#BDBDBD", guide = "none") + ggplot2::scale_colour_identity(guide = "none") + ggplot2::coord_sf(expand = FALSE) + 
        ggplot2::labs(x = NULL, y = NULL) + cowplot::theme_cowplot() + ggplot2::theme(legend.position = "none", axis.line = ggplot2::element_blank())
