    p_c <- ggplot2::ggplot(metrics, ggplot2::aes(x = .data$weekday, y = .data$duration_above_250_daytime_h)) + ggplot2::geom_boxplot(width = 0.5, fill = "white", na.rm = TRUE) + ggplot2::scale_x_discrete(expand = c(0, 0)) + ggplot2::coord_cartesian(xlim = c(0.5, 5.5)) + ggplot2::labs(y = expression(TAT[250] ~ "(Hrs)"), x = NULL, tag = "C") + cowplot::theme_cowplot(font_size = 9.5) + ggplot2::theme(plot.margin = ggplot2::margin(3, 5, 5, 24), plot.tag.position = c(0.1, 0.99))
